#[tokio::test]
async fn device_flow_errors_and_slow_down_follow_go() {
    let device = json!({"status":200,"body":r#"{"device_code":"d","user_code":"u","interval":1,"expires_in":600}"#});
    let poll = |status: u16, body: &str| json!({"status":status,"body":body});
    let cases = [
        (
            poll(400, r#"{"error":"access_denied"}"#),
            "meta auth: access was denied by user",
        ),
        (
            poll(400, r#"{"error":"expired_token"}"#),
            "meta auth: device code has expired",
        ),
        (
            poll(400, r#"{"error":"invalid_client","error_description":"bad client"}"#),
            "meta auth: error from authorization server: invalid_client: bad client",
        ),
        (
            poll(200, r#"{"token_type":"bearer"}"#),
            "meta auth: response missing access_token",
        ),
    ];
    for (answer, message) in cases {
        let mock = Mock::start(&json!([device, answer])).await;
        let auth = login_auth(&mock.url);
        let code = auth.start_device_flow().await.unwrap();
        assert_eq!(auth.wait_for_authorization(&code).await.unwrap_err(), message);
    }
    // slow_down adds five server seconds; unknown non-JSON answers keep polling.
    let mock = Mock::start(&json!([
        device,
        poll(400, r#"{"error":"slow_down"}"#),
        poll(502, "bad gateway"),
        poll(200, r#"{"access_token":"dca:t","expires_in":0}"#),
        poll(500, "mint down"),
    ]))
    .await;
    let auth = login_auth(&mock.url);
    let code = auth.start_device_flow().await.unwrap();
    let started = tokio::time::Instant::now();
    let bundle = auth.wait_for_authorization(&code).await.unwrap();
    assert!(
        started.elapsed() >= Duration::from_millis(10 + 60 + 60),
        "slow_down widened the interval"
    );
    assert_eq!(bundle.token.access_token, "dca:t");
    assert_eq!(bundle.minted, None, "a failed mint keeps the DCA-only bundle");
    // The deadline is the device code's expires_in.
    let mock = Mock::start(&json!([
        {"status":200,"body":r#"{"device_code":"d","user_code":"u","interval":1,"expires_in":3}"#},
        poll(400, r#"{"error":"authorization_pending"}"#),
        poll(400, r#"{"error":"authorization_pending"}"#),
        poll(400, r#"{"error":"authorization_pending"}"#),
    ]))
    .await;
    let auth = login_auth(&mock.url);
    let code = auth.start_device_flow().await.unwrap();
    assert_eq!(
        auth.wait_for_authorization(&code).await.unwrap_err(),
        "meta auth: authorization timed out or canceled: context deadline exceeded"
    );
    // Device authorization failures.
    let mock = Mock::start(&json!([
        poll(400, " nope "),
        poll(200, r#"{"device_code":"d","user_code":" "}"#),
        poll(200, r#"{"device_code":"d","user_code":"u","interval":1.5}"#),
    ]))
    .await;
    let auth = login_auth(&mock.url);
    crate::device_fixture::assert_go_message_without_body(
        "device flow 400",
        &auth.start_device_flow().await.unwrap_err(),
        "meta device flow failed (HTTP 400): nope",
    );
    assert_eq!(
        auth.start_device_flow().await.unwrap_err(),
        "meta device flow: response missing required device_code or user_code"
    );
    assert!(
        auth.start_device_flow()
            .await
            .unwrap_err()
            .starts_with("meta device flow: parse response: ")
    );
}

#[test]
fn auth_records_decode_like_go_json_unmarshal() {
    // Go json.Unmarshal into DeviceCodeResponse, TokenData and MintedKeyResponse.
    let fx = fixture("meta", "decode");
    let string = |v: &Value, k: &str| v[k].as_str().unwrap_or_default().to_owned();
    let int = |v: &Value, k: &str| v[k].as_i64().unwrap_or_default();
    let boolean = |v: &Value, k: &str| v[k].as_bool().unwrap_or_default();
    for case in fx["extra"]["cases"].as_array().unwrap() {
        let input = case["input"].as_str().unwrap();
        let raw = input.as_bytes();
        let err = |r: &Value| r["err"].as_str().unwrap().to_owned();

        let go = &case["device"];
        match crate::meta_auth::DeviceCode::decode_for_test(raw) {
            Ok(c) => {
                assert_eq!(err(go), "", "device {input}");
                let v = &go["value"];
                assert_eq!(
                    (
                        c.device_code,
                        c.user_code,
                        c.verification_uri,
                        c.verification_uri_complete
                    ),
                    (
                        string(v, "device_code"),
                        string(v, "user_code"),
                        string(v, "verification_uri"),
                        string(v, "verification_uri_complete")
                    ),
                    "device {input}"
                );
                assert_eq!(
                    (c.expires_in, c.interval),
                    (int(v, "expires_in"), int(v, "interval")),
                    "device {input}"
                );
            }
            Err(e) => assert_eq!(e, err(go), "device {input}"),
        }

        let go = &case["token"];
        let (t, result) = crate::meta_auth::TokenData::decode_for_test(raw);
        assert_eq!(result.err().unwrap_or_default(), err(go), "token {input}");
        let v = &go["value"];
        assert_eq!(
            (t.access_token, t.token_type, t.error, t.error_description),
            (
                string(v, "access_token"),
                string(v, "token_type"),
                string(v, "error"),
                string(v, "error_description")
            ),
            "token {input}"
        );
        assert_eq!(
            (t.expires_in, t.expires_at),
            (int(v, "expires_in"), int(v, "expires_at")),
            "token {input}"
        );

        let go = &case["mint"];
        match MintedKey::decode(raw) {
            Ok(m) => {
                assert_eq!(err(go), "", "mint {input}");
                let v = &go["value"];
                assert_eq!(
                    (
                        m.api_key,
                        m.base_url,
                        m.user_email,
                        m.user_full_name,
                        m.subs_tier_name,
                        m.subs_tier_id
                    ),
                    (
                        string(v, "api_key"),
                        string(v, "base_url"),
                        string(v, "user_email"),
                        string(v, "user_full_name"),
                        string(v, "subs_tier_name"),
                        string(v, "subs_tier_id")
                    ),
                    "mint {input}"
                );
                assert_eq!(
                    (
                        m.is_subs_active,
                        m.has_payment_method,
                        m.require_payment,
                        m.can_subscribe
                    ),
                    (
                        boolean(v, "is_subs_active"),
                        boolean(v, "has_payment_method"),
                        boolean(v, "require_payment"),
                        boolean(v, "can_subscribe")
                    ),
                    "mint {input}"
                );
            }
            Err(e) => assert_eq!(e, err(go), "mint {input}"),
        }
    }
}

